Given k sorted linked lists of different sizes, we need to merge them into a single list while maintaining their sorted order.Examples: Input: Output: Explanation: Merged lists in a sorted order where every element is greater than the previous element.Input:  Output:  Try It YourselfTable of Content[Naive Approach - 1] - By Merging List One by One[Naive Approach - 2] - By repeatedly selecting the minimum node[Expected Approach - 1] - Using Min Heap (Works better for unequal sized lists)[Expected Approach - 2] - Using Divide and Conquer (Works better for equal sized lists)[Naive Approach - 1] - By Merging List One by OneThe idea is to initialize the result as empty. Now one by one merge every linked list into the resultant list using the idea of merging two sorted linked lists. We always consider the result as first list and other list as second. At the end, we return result.
            C++

    #include <iostream>
#include<vector>
using namespace std;

class Node {
public:
    int data;
    Node* next;
    Node(int x) {
        data = x;
        next = nullptr;
    }
};

// Function to merge only 2 lists
Node* mergeTwo(Node* head1, Node* head2) {

    // Create a dummy node to simplify 
    // the merging process
    Node* dummy = new Node(-1);
    Node* curr = dummy;

    // Iterate through both linked lists
    while (head1 != nullptr && head2 != nullptr) {

        // Add the smaller node to the merged list
        if (head1->data <= head2->data) {
            curr->next = head1;
            head1 = head1->next;
        } else {
            curr->next = head2;
            head2 = head2->next;
        }
        curr = curr->next;
    }

    // If any list is left, append it to
    // the merged list
    if (head1 != nullptr) {
        curr->next = head1;
    } else {
        curr->next = head2;
    }

    // Return the merged list starting
    // from the next of dummy node
    return dummy->next;
}

// Function to merge K sorted linked lists
Node* mergeKLists(vector<Node*>& arr) {

    // Initialize result as empty
    Node *res = nullptr;

    // One by one merge all lists with 
    // res and keep updating res
    for (Node *node : arr) 
        res = mergeTwo(res, node);

    return res;
}

void printList(Node* node) {
    while (node != nullptr) {
        cout << node->data;
        if(node->next)
        cout<<" -> ";
        node = node->next;
    }
}

int main() {
    int k = 3; 

    vector<Node*> arr(k);

    arr[0] = new Node(1);
    arr[0]->next = new Node(3);
    arr[0]->next->next = new Node(5);
    arr[0]->next->next->next = new Node(7);

    arr[1] = new Node(2);
    arr[1]->next = new Node(4);
    arr[1]->next->next = new Node(6);
    arr[1]->next->next->next = new Node(8);

    arr[2] = new Node(0);
    arr[2]->next = new Node(9);
    arr[2]->next->next = new Node(10);
    arr[2]->next->next->next = new Node(11);

    Node* head = mergeKLists(arr);

    printList(head);

    return 0;
}


